107: /**
108:  * The New Stats screen's controller.
109:  *
110:  * It owns the screen state, the durable user choices, the response cache and
111:  * the in-flight request ledger, and it translates user intent into remote
112:  * requests. Every value it publishes is something the page renders, so the
113:  * screen stays coherent without the page recomputing anything itself.
114:  */
115: export class NewStatsStore {
116:   private state: Record<string, Object> = {};
117:   private persistence: Record<string, Object> = {};
118:   private leaf: NewStatsLeaf;
119:   private repository: NewStatsConfigurationRepository;
120:   private remote: NewStatsRemoteSource;
121:   private cache: NewStatsResponseCache = new NewStatsResponseCache();
122:   private ledger: NewStatsRequestLedger;
123:   private today: string;
124:   private listeners: Array<() => void> = [];
125:   private siteId: number;
126:   private variant: string = DEFAULT_VARIANT;
127: 
128:   private constructor(repository: NewStatsConfigurationRepository, input: NewStatsInput) {
129:     this.repository = repository;
130:     this.leaf = input.leaf;
131:     this.remote = new NewStatsScriptedRemoteSource();
132:     this.today = newStatsToday();
133:     this.ledger = new NewStatsRequestLedger(0);
134:     this.siteId = newStatsReadNumber(this.state, 'siteId');
135:   }
