137:   static async create(context: common.UIAbilityContext, input: NewStatsInput,
138:     initialize: boolean): Promise<NewStatsStore> {
139:     const repository: NewStatsConfigurationRepository = await NewStatsConfigurationRepository.open(context);
140:     if (initialize) {
141:       await repository.clear();
142:       await repository.writeSession(input.state);
143:       const seeded: NewStatsConfiguration = defaultConfigurationFrom(input.persistence);
144:       await repository.writeConfiguration(seeded);
145:     }
146:     const store: NewStatsStore = new NewStatsStore(repository, input);
147:     store.state = input.state;
148:     store.persistence = input.persistence;
149:     store.bootstrap();
150:     await store.refreshFromRepository();
151:     return store;
152:   }
