156:   /**
157:    * Brings the screen state in line with the durable configuration without
158:    * inventing values for anything the environment did not already describe.
159:    */
160:   private bootstrap(): void {
161:     this.siteId = newStatsReadNumber(this.state, 'siteId');
162:     const clock: string = newStatsReadString(this.state, 'clockDate');
163:     const seededToday: string = newStatsReadString(this.state, 'today');
164:     if (clock.length > 0) {
165:       this.today = clock;
166:     } else if (seededToday.length > 0) {
167:       this.today = seededToday;
168:     }
169: 
170:     // The durable preference is the seed of truth: when the state has not
171:     // chosen a metric yet, the metric the user last preferred is what the
172:     // screen starts from, so an hourly window's fallback never becomes the
173:     // stored choice.
174:     if (this.state['selectedMetric'] === undefined) {
175:       const preferred: string = newStatsReadString(this.state, 'persistedMetric');
176:       const stored: string = newStatsReadString(this.persistence, 'selectedMetric');
177:       const seed: string = preferred.length > 0 ? preferred : stored;
178:       this.state['selectedMetric'] = seed.length > 0 ? seed : NewStatsMetric.VIEWS;
179:     }
180:     if (this.state['persistedMetric'] === undefined) {
181:       this.state['persistedMetric'] = this.selectedMetric();
182:     }
183:     if (this.state['period'] === undefined) {
184:       // Fall back to the persisted origin so a restored screen resumes on the
185:       // period the user left, keeping that period's meaning.
186:       const origin: string = this.initialPeriodOrigin();
187:       this.state['period'] = origin.length > 0 ? origin : NewStatsPeriodType.LAST_7_DAYS;
188:     }
189:     if (this.state['chartState'] === undefined) {
190:       this.state['chartState'] = NewStatsContentState.LOADED;
191:     }
192:     if (this.state['loadingPlaceholderVisible'] === undefined) {
193:       this.state['loadingPlaceholderVisible'] = false;
194:     }
195:     if (this.state['metricPickedOnCurrentPeriod'] === undefined) {
196:       this.state['metricPickedOnCurrentPeriod'] = false;
197:     }
198: 
199:     const committed: NewStatsPeriod = this.restoreInitialPeriod();
200:     this.writePeriod('committedPeriod', committed);
201:     if (this.state['effectivePeriod'] === undefined) {
202:       this.writePeriod('effectivePeriod', committed);
203:     }
204:     if (this.state['chartType'] === undefined) {
205:       this.state['chartType'] = 'bar';
206:     }
207:     this.state['supportedMetrics'] = supportedNewStatsChartMetrics(committed, this.hourlySeriesMetrics());
208:     if (this.state['selectedBar'] === undefined) {
209:       this.clearBucketSelectionRecord();
210:     }
211:     if (this.state['selectedLocationType'] === undefined) {
212:       this.state['selectedLocationType'] = NewStatsLocationType.COUNTRIES;
213:     }
214:     if (this.state['requestIdentity'] === undefined) {
215:       this.state['requestIdentity'] = this.requestIdentityRecord(NEW_STATS_SURFACE_VIEWS_CHART);
216:     }
217:     if (this.state['displayedMetric'] === undefined) {
218:       this.state['displayedMetric'] = this.displayedMetricFor(committed);
219:     }
220:     if (this.state['chartMetric'] === undefined) {
221:       this.state['chartMetric'] = newStatsReadString(this.state, 'displayedMetric');
222:     }
223:     this.state['requestIdentity'] = this.requestIdentityRecord(NEW_STATS_SURFACE_VIEWS_CHART);
224:     this.state['canNavigateForward'] = canPageNewStatsForward(committed, this.today);
225:     this.state['canNavigateBackward'] = true;
226: 
227:     this.adoptSeededCacheEntry();
228:     this.registerSeededInFlightRequests();
229:     this.recomputeChartSeries();
230:   }
