271:   /** The origin the screen starts on: explicit state, then persisted choice. */
272:   private initialPeriodOrigin(): string {
273:     const fromPersistence: string = newStatsReadString(this.persistence, 'periodOrigin');
274:     if (fromPersistence.length > 0) {
275:       return fromPersistence;
276:     }
277:     const persisted: string = newStatsReadString(this.persistence, 'period');
278:     if (persisted.length > 0) {
279:       return persisted;
280:     }
281:     return newStatsReadString(this.state, 'persistedOrigin');
282:   }
