336:   private readEffectivePeriod(): NewStatsPeriod {
337:     const raw: Record<string, Object> = newStatsReadRecord(this.state, 'effectivePeriod');
338:     const start: string = newStatsReadString(raw, 'start');
339:     const end: string = newStatsReadString(raw, 'end');
340:     const origin: string = newStatsReadString(raw, 'origin');
341:     const kind: string = newStatsReadString(raw, 'kind');
342:     if (start.length > 0 && end.length > 0) {
343:       return {
344:         kind: kind.length > 0 ? kind : NewStatsPeriodKind.CUSTOM,
345:         type: 'custom',
346:         origin: origin.length > 0 ? origin : 'custom',
347:         start: start,
348:         end: end
349:       };
350:     }
351:     return this.readCommittedPeriod();
352:   }
