376:   private writePeriod(key: string, period: NewStatsPeriod): void {
377:     const encoded: Record<string, Object> = {};
378:     encoded['kind'] = period.kind;
379:     encoded['type'] = period.type;
380:     encoded['origin'] = period.origin;
381:     encoded['start'] = period.start;
382:     encoded['end'] = period.end;
383:     this.state[key] = encoded;
