412:   private requestIdentityRecord(surface: string): Record<string, Object> {
413:     const identity: NewStatsRequestIdentity = this.requestIdentityFor(surface);
414:     const encoded: Record<string, Object> = {};
415:     encoded['surface'] = identity.surface;
416:     encoded['siteId'] = identity.siteId;
417:     encoded['today'] = identity.today;
418:     encoded['period'] = identity.period;
419:     encoded['variant'] = identity.variant;
420:     return encoded;
421:   }
