597:   /**
598:    * Chooses what the chart can actually draw for the current window. The
599:    * user's preference is never overwritten here: a metric the window cannot
600:    * represent is simply not drawn.
601:    */
602:   /**
603:    * The metrics the hourly endpoint publishes for this site. Sites that expose
604:    * more than views there get those metrics treated as drawable too.
605:    */
606: private hourlySeriesMetrics(): string[] | undefined {
607:     const declared: string[] = newStatsReadStringArray(this.state, 'hourlySeriesMetrics');
608:     return declared.length > 0 ? declared : undefined;
609:   }
610: 
611:   private displayedMetricFor(period: NewStatsPeriod): string {
612:     const chosen: string = this.selectedMetric();
613:     if (supportsNewStatsChartMetric(period, chosen, this.hourlySeriesMetrics())) {
614:       return chosen;
615:     }
616:     return fallbackNewStatsMetric(period, this.hourlySeriesMetrics());
617:   }
618: 
619:   /**
620:    * Resolves the chart's metric state for the current window.
621:    *
622:    * `explicitPick` distinguishes the two ways an unsupported metric can arise.
623:    * When the user picked it on this window, the chart says so; when it is only
624:    * a preference carried over from somewhere else, the chart quietly draws a
625:    * metric it can represent and keeps the preference for a compatible window.
626:    */
627:   private syncChartStateAfterPeriodChange(explicitPick: boolean): void {
628:     const period: NewStatsPeriod = this.readCommittedPeriod();
629:     const chosen: string = this.selectedMetric();
630:     const drawable: boolean = supportsNewStatsChartMetric(period, chosen, this.hourlySeriesMetrics());
631:     const pickedHere: boolean = explicitPick || newStatsReadBoolean(this.state, 'metricPickedOnCurrentPeriod');
632:     this.state['supportedMetrics'] = supportedNewStatsChartMetrics(period, this.hourlySeriesMetrics());
633:     if (!drawable && pickedHere) {
634:       // The user asked for something this window cannot draw. The header keeps
635:       // naming the metric they asked for and the chart reports it as
636:       // unavailable, rather than silently drawing a different metric.
637:       this.state['displayedMetric'] = chosen;
638:       this.state['unavailableMetric'] = chosen;
639:       this.state['chartState'] = NewStatsContentState.METRIC_UNAVAILABLE;
640:       return;
641:     }
642:     this.state['displayedMetric'] = this.displayedMetricFor(period);
643:     if (drawable) {
644:       this.state['unavailableMetric'] = '';
645:     }
646:     if (this.state['chartState'] !== NewStatsContentState.ERROR) {
647:       this.state['chartState'] = NewStatsContentState.LOADED;
648:     }
649:   }
