698:   /**
699:    * Applies a response only when it belongs to the current refresh boundary.
700:    * A result that started before the boundary is discarded rather than
701:    * repopulating refreshed state.
702:    */
703:   private async applyResponse(response: NewStatsRemoteResponse, event: Record<string, Object>): Promise<boolean> {
704:     if (!this.ledger.isCurrent(response.generation)) {
705:       await this.emit({
706:         name: 'discardStaleStatsResult',
707:         source: 'Index.NewStatsStore.ledger',
708:         siteId: this.siteId,
709:         channel: response.channel
710:       });
711:       this.ledger.finish(response.channel);
712:       return false;
713:     }
714:     this.ledger.finish(response.channel);
715:     if (response.channel === NEW_STATS_CHANNEL_REGION_VIEWS) {
716:       await this.applyRegionResponse(response, event);
717:       return true;
718:     }
719:     if (response.outcome === NEW_STATS_OUTCOME_SUCCESS) {
720:       // The generation check above guarantees this response's window is still
721:       // the current one, so the identity read here is the one it was sent under.
722:       this.applyStatsPayload(response.payload, response.channel, event,
723:         this.requestIdentityFor(NEW_STATS_SURFACE_VIEWS_CHART), response.windowKey);
724:       return true;
725:     }
726:     this.applyStatsFailure(response, response.outcome === NEW_STATS_OUTCOME_NETWORK_ERROR);
727:     return false;
728:   }
729: 
730:   private applyStatsPayload(payload: Record<string, Object>, channel: string, event: Record<string, Object>,
731:     identity: NewStatsRequestIdentity, responseWindowKey: string): void {
732:     const loaded: Record<string, Object> = newStatsReadRecord(payload, 'totals');
733:     if (Object.keys(loaded).length > 0) {
734:       const descriptor: Record<string, Object> = {};
735:       descriptor['totals'] = loaded;
736:       const points: Object[] = newStatsReadArray(payload, 'points');
737:       if (points.length > 0) {
738:         descriptor['points'] = points;
739:       }
740:       this.state['loadedPeriodData'] = descriptor;
741:     }
742:     const views: Object | undefined = payload[KEY_VIEWS];
743:     if (views !== undefined && views !== null) {
744:       this.state[KEY_VIEWS] = views as number;
745:       this.state['visibleViews'] = views as number;
746:     }
747:     this.state['loadingPlaceholderVisible'] = false;
748:     this.state['needsRevalidation'] = false;
749:     this.state['refreshing'] = false;
750:     this.state['backgroundRevalidationPending'] = false;
751:     // A successful load resolves any outstanding failure state.
752:     this.state['retryAvailable'] = false;
753:     this.state['lastError'] = '';
754:     this.state['revalidationError'] = '';
755:     // A period load does not resolve a metric the window cannot draw: that
756:     // state only changes when the metric or the period does.
757:     if (this.state['chartState'] !== NewStatsContentState.METRIC_UNAVAILABLE) {
758:       this.state['chartState'] = NewStatsContentState.LOADED;
759:     }
760:     this.recomputeChartSeries();
761:     // Only a response that actually carried data becomes the cached value, and
762:     // it is then marked as revalidated. An empty answer must not be cached, or
763:     // a cold start would look like a valid result on the next visit.
764:     if (Object.keys(payload).length > 0) {
765:       // Keyed by the identity the request was made under, so a response can
766:       // never be filed against a different window.
767:       const key: string = newStatsRequestIdentityKey(identity) + '|' + responseWindowKey;
768:       this.cache.write(key, identity, this.cachePayload(), this.today, false);
769:       if (channel === NEW_STATS_CHANNEL_REFRESH) {
770:         this.state['cachedViewsForNextVisit'] = newStatsReadNumber(this.state, KEY_VIEWS);
771:       }
772:     }
773:     void event;
774:   }
775: 
776:   /**
777:    * The cache holds the figures the screen would show for this window, so a
778:    * cache hit can rebuild the whole card rather than just its headline number.
779:    */
780:   private cachePayload(): Record<string, Object> {
781:     const payload: Record<string, Object> = {};
782:     const loaded: Record<string, Object> = newStatsReadRecord(this.state, 'loadedPeriodData');
783:     const totals: Record<string, Object> = newStatsReadRecord(loaded, 'totals');
784:     const keys: string[] = Object.keys(totals);
785:     for (const key of keys) {
786:       payload[key] = totals[key];
787:     }
788:     const points: Object[] = newStatsReadArray(loaded, 'points');
789:     if (points.length > 0) {
790:       payload['points'] = points;
791:     }
792:     payload[KEY_VIEWS] = newStatsReadNumber(this.state, KEY_VIEWS);
793:     return payload;
794:   }
795: 
796:   /**
797:    * A foreground failure stops loading and offers the ordinary retry. A
798:    * background revalidation failure keeps whatever cached content is already
799:    * usable and stays out of the way.
800:    */
801:   private applyStatsFailure(response: NewStatsRemoteResponse, offline: boolean): void {
802:     const key: string = this.cacheKeyFor(NEW_STATS_SURFACE_VIEWS_CHART);
803:     const cached: NewStatsCacheEntry | undefined = this.cache.read(key);
804:     this.state['backgroundRevalidationPending'] = false;
805:     if (response.channel === NEW_STATS_CHANNEL_REVALIDATION && cached !== undefined) {
806:       // The cached result stays exactly as it was, and stays revalidation-due.
807:       this.restoreCachedEntry(cached);
808:       this.state['chartState'] = NewStatsContentState.LOADED;
809:       this.state['loadingPlaceholderVisible'] = false;
810:       this.state['needsRevalidation'] = true;
811:       this.state['revalidationError'] = offline ? 'offline' : response.errorCode;
812:       this.cache.write(key, cached.identity, cached.payload, cached.storedOn, true);
813:       return;
814:     }
815:     if (cached !== undefined) {
816:       // Cached content is still the best thing to show, but the foreground
817:       // attempt has ended, so the screen must stop loading and offer a retry.
818:       this.restoreCachedEntry(cached);
819:       this.state['chartState'] = NewStatsContentState.ERROR;
820:       this.state['loadingPlaceholderVisible'] = false;
821:       this.state['retryAvailable'] = true;
822:       this.state['needsRevalidation'] = true;
823:       this.state['lastError'] = offline ? 'offline' : response.errorCode;
824:       return;
825:     }
826:     this.state['chartState'] = NewStatsContentState.ERROR;
827:     this.state['loadingPlaceholderVisible'] = false;
828:     this.state['refreshing'] = false;
829:     this.state['retryAvailable'] = true;
830:     this.state['lastError'] = offline ? 'offline' : response.errorCode;
831:   }
832: 
833:   private restoreCachedEntry(entry: NewStatsCacheEntry): void {
834:     const cachedPoints: Object[] = newStatsReadArray(entry.payload, 'points');
835:     const cachedTotals: Record<string, Object> = {};
836:     const keys: string[] = Object.keys(entry.payload);
837:     for (const key of keys) {
838:       if (key === 'points') {
839:         continue;
840:       }
841:       cachedTotals[key] = entry.payload[key];
842:     }
843:     if (Object.keys(cachedTotals).length > 0 || cachedPoints.length > 0) {
844:       const descriptor: Record<string, Object> = {};
845:       if (Object.keys(cachedTotals).length > 0) {
846:         descriptor['totals'] = cachedTotals;
847:       }
848:       if (cachedPoints.length > 0) {
849:         descriptor['points'] = cachedPoints;
850:       }
851:       this.state['loadedPeriodData'] = descriptor;
852:       this.state['currentPoints'] = cachedPoints;
853:     }
854:     const views: Object | undefined = entry.payload[KEY_VIEWS];
855:     if (views !== undefined && views !== null) {
856:       this.state[KEY_VIEWS] = views as number;
857:       this.state['visibleViews'] = views as number;
858:       this.state['cachedViewsForNextVisit'] = views as number;
859:     }
860:     this.state['loadingPlaceholderVisible'] = false;
861:     this.recomputeChartSeries();
862:   }
