866:   private adoptSeededCacheEntry(): void {
867:     const seededIdentity: Record<string, Object> = newStatsReadRecord(this.state, 'requestIdentity');
868:     const cached: Record<string, Object> = newStatsReadRecord(this.state, 'displayedCachedResult');
869:     const site: number = newStatsReadNumber(seededIdentity, 'siteId');
870:     const surface: string = newStatsReadString(seededIdentity, 'surface');
871:     const day: string = newStatsReadString(seededIdentity, 'today');
872:     const period: string = newStatsReadString(seededIdentity, 'period');
873:     const variant: string = newStatsReadString(seededIdentity, 'variant');
874:     const seededViews: number = newStatsReadNumber(cached, KEY_VIEWS);
875:     if (surface.length === 0 || Object.keys(cached).length === 0) {
876:       return;
877:     }
878:     const identity: NewStatsRequestIdentity = {
879:       surface: surface,
880:       siteId: site,
881:       today: day.length > 0 ? day : this.today,
882:       period: period,
883:       variant: variant
884:     };
885:     // Key the restored entry exactly the way a live lookup would, so a revisit
886:     // finds it without any special-casing.
887:     const entry: NewStatsCacheEntry = {
888:       key: this.cacheKeyFor(NEW_STATS_SURFACE_VIEWS_CHART),
889:       identity: identity,
890:       payload: cached,
891:       storedOn: day.length > 0 ? day : this.today,
892:       needsRevalidation: newStatsReadBoolean(this.state, 'needsRevalidation')
893:     };
894:     this.cache.adopt(entry);
895:     this.state[KEY_VIEWS] = seededViews;
896:     this.state['visibleViews'] = seededViews;
897:   }
