991:   private async fetchPeriodData(event: Record<string, Object>): Promise<void> {
992:     const generation: number = this.ledger.currentGeneration();
993:     this.state['periodFetchCount'] = newStatsReadNumber(this.state, 'periodFetchCount') + 1;
994:     this.state['loadingPlaceholderVisible'] = true;
995:     if (this.state['chartState'] !== NewStatsContentState.METRIC_UNAVAILABLE) {
996:       this.state['chartState'] = NewStatsContentState.LOADING;
997:     }
998:     this.state['refreshing'] = false;
999:     await this.emit({
1000:       name: 'fetchStatsForPeriod',
1001:       source: 'Index.NewStatsStore.period',
1002:       siteId: this.siteId,
1003:       selectedMetric: this.displayedMetric(),
1004:       selectedPeriodType: this.readCommittedPeriod().origin,
1005:       forceRefresh: newStatsReadBoolean(event, 'forceRefresh'),
1006:       period: this.requestIdentityRecord(NEW_STATS_SURFACE_VIEWS_CHART)
1007:     });
1008:     const responses: NewStatsRemoteResponse[] = await this.request(NEW_STATS_CHANNEL_PERIOD_DATA,
1009:       NEW_STATS_SURFACE_VIEWS_CHART, false, event, generation);
1010:     for (const response of responses) {
1011:       await this.applyResponse(response, event);
1012:     }
