1019:   private async onSelectMetric(event: Record<string, Object>): Promise<void> {
1020:     const metric: string = newStatsReadString(event, 'metric');
1021:     if (metric.length === 0) {
1022:       return;
1023:     }
1024:     this.state['selectedMetric'] = metric;
1025:     // The preference is durable regardless of whether this window can draw it.
1026:     this.state['persistedMetric'] = metric;
1027:     this.state['metricPickedOnCurrentPeriod'] = true;
1028:     this.persistence['selectedMetric'] = metric;
1029:     this.syncChartStateAfterPeriodChange(true);
1030:     await this.emit({ name: 'selectChartMetric', selectedMetric: metric, metric: metric, siteId: this.siteId });
1031:     // The period response already carries every metric, so this only redraws.
1032:     this.recomputeChartSeries();
