1035:   private async onSelectPeriod(event: Record<string, Object>): Promise<void> {
1036:     const origin: string = newStatsReadString(event, 'period');
1037:     if (origin.length === 0) {
1038:       return;
1039:     }
1040:     const period: NewStatsPeriod = resolveNewStatsPeriod(origin, this.today);
1041:     this.state['period'] = origin;
1042:     this.commitPeriod(period);
1043:     this.state['metricPickedOnCurrentPeriod'] = false;
1044:     this.syncChartStateAfterPeriodChange(false);
1045:     this.recomputeChartSeries();
1046:     await this.emit({
1047:       name: 'selectStatsPeriod',
1048:       originPeriodType: this.readCommittedPeriod().origin,
1049:       origin: origin,
1050:       selectedPeriodType: origin,
1051:       customStart: period.start,
1052:       customEnd: period.end,
1053:       siteId: this.siteId
1054:     });
1055:     await this.fetchPeriodData(event);
