1058:   /** Every committed period change invalidates any soft bucket selection. */
1059:   private commitPeriod(period: NewStatsPeriod): void {
1060:     // Committing a window opens a new refresh boundary, so a period response
1061:     // that is still in flight for the previous window cannot land on this one.
1062:     this.ledger.invalidate();
1063:     this.writePeriod('committedPeriod', period);
1064:     this.writePeriod('effectivePeriod', period);
1065:     this.clearBucketSelectionRecord();
1066:     this.state['period'] = period.origin;
1067:     this.state['canNavigateForward'] = canPageNewStatsForward(period, this.today);
1068:     this.state['canNavigateBackward'] = true;
1069:     this.state['persistedOrigin'] = period.origin;
1070:     const persistedPeriod: Record<string, Object> = {};
1071:     persistedPeriod['type'] = 'custom';
1072:     persistedPeriod['start'] = period.start;
1073:     persistedPeriod['end'] = period.end;
1074:     this.state['persistedPeriod'] = persistedPeriod;
1075:     this.state['restoredOrigin'] = period.origin;
1076:     this.persistence['period'] = period.origin;
1077:     this.persistence['periodOrigin'] = period.origin;
1078:     this.persistence['periodStart'] = period.start;
1079:     this.persistence['periodEnd'] = period.end;
1080:     this.persistence['periodKind'] = period.kind;
1081:   }
