1083:   private async onTapChartBucket(event: Record<string, Object>): Promise<void> {
1084:     const index: number = newStatsReadNumber(event, 'index');
1085:     const buckets: NewStatsBucket[] = this.buckets();
1086:     const bucket: NewStatsBucket | undefined = this.resolveTapTarget(index, buckets);
1087:     if (bucket === undefined) {
1088:       // A placeholder for a bucket that has not happened yet is not actionable.
1089:       return;
1090:     }
1091:     if (this.selectedBucketIndex() === index) {
1092:       this.clearBucketSelection();
1093:       return;
1094:     }
1095:     const bar: Record<string, Object> = {};
1096:     bar['index'] = bucket.index;
1097:     bar['rawPeriod'] = bucket.rawPeriod;
1098:     bar['canDrillDown'] = bucket.canDrillDown;
1099:     this.setBucketSelectionRecord(bar);
1100:     const effective: NewStatsPeriod = {
1101:       kind: NewStatsPeriodKind.CUSTOM,
1102:       type: 'custom',
1103:       origin: 'custom',
1104:       start: bucket.rawPeriod,
1105:       end: bucket.rawPeriod
1106:     };
1107:     this.writePeriod('effectivePeriod', effective);
1108:     this.state['canDrillDown'] = bucket.canDrillDown;
1109:     this.recomputeChartSeries();
1110:     await this.emit({
1111:       name: 'chartBucketSelected',
1112:       siteId: this.siteId,
1113:       index: bucket.index,
1114:       rawPeriod: bucket.rawPeriod,
1115:       canDrillDown: bucket.canDrillDown
1116:     });
1117:   }
1118: 
1119:   private resolveTapTarget(index: number, buckets: NewStatsBucket[]): NewStatsBucket | undefined {
1120:     if (index >= 0 && index < buckets.length) {
1121:       const bucket: NewStatsBucket = buckets[index];
1122:       if (bucket.isUpcoming || bucket.rawPeriod.length === 0) {
1123:         return undefined;
1124:       }
1125:       return bucket;
1126:     }
1127:     return undefined;
1128:   }
1129: 
1130:   private clearBucketSelection(): void {
1131:     this.clearBucketSelectionRecord();
1132:     this.writePeriod('effectivePeriod', this.readCommittedPeriod());
1133:     this.state['canDrillDown'] = false;
1134:     this.recomputeChartSeries();
1135:   }
