1137:   private onDrillIntoSelectedBucket(event: Record<string, Object>): Promise<void> {
1138:     const bucket: NewStatsBucket | undefined = this.selectedBucket();
1139:     if (bucket === undefined || !bucket.canDrillDown) {
1140:       return Promise.resolve();
1141:     }
1142:     const target: NewStatsPeriod = {
